const frostFlowerSheet=new Image();frostFlowerSheet.assetSrc='assets/frost-flower-v1.png';
function frostFlowerAlly(e,other,checkMembership=true){return other!==e&&/^r\d+e\d+$/.test(other.species||'')&&!other.boss&&!other.secret&&!other.exRank&&!other.dummy&&Number.isFinite(other.hp)&&other.hp>0&&Number.isFinite(other.max)&&other.max>0&&(!checkMembership||enemies.includes(other))&&dist(e,other)<=320+1e-8&&lineClear(e,other);}
function frostFlowerTargets(e){return enemies.filter(other=>other.hp<other.max&&frostFlowerAlly(e,other,false)).sort((a,b)=>dist(e,a)-dist(e,b)).slice(0,3);}
function beginFrostFlower(e,targets=frostFlowerTargets(e)){e.state='attack';e.elapsed=0;e.struck=false;e.attack={pattern:'frostFlowerMend',bespoke:true,windup:.9,origin:{x:e.x,y:e.y},targets:[...targets],links:[...targets],linkTimer:.2,pulses:0,fired:false};}
function interruptFrostFlower(e){e.attack=null;e.state='idle';e.elapsed=0;e.t=3;e.frostWilt=1.2;}
const frostFlowerHitBase=hit;hit=(e,d)=>{let before=e.hp,result=frostFlowerHitBase(e,d);if(e.species==='r5e6'&&e.hp>0&&e.hp<before&&!e.dotTick&&Number.isFinite(d)&&d>0&&e.attack?.pattern==='frostFlowerMend'&&!e.attack.fired)interruptFrostFlower(e);return result;};
const frostFlowerAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r5e6')return frostFlowerAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);e.frostWilt=Math.max(0,(e.frostWilt||0)-dt);if(e.frostWilt>0){e.t=Math.max(0,e.t-dt);e.state='idle';return;}
 let a=e.attack;if(a?.pattern!=='frostFlowerMend'){
  e.t-=dt;e.nav=(e.nav||0)-dt;e.supportScan=(e.supportScan||0)-dt;let d=dist(e,p);e.state='idle';if(d>750&&!e.aware)return;let clear=lineClear(e,p);
  if(e.t<=0&&e.supportScan<=0){e.supportScan=.5;let targets=frostFlowerTargets(e);if(targets.length||d<=200&&clear){beginFrostFlower(e,targets);return;}}
  if(d<=180)return;if(e.nav<=0){e.nav=.8;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,42*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,18)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;
 }
 if(dist(e,a.origin)>24){interruptFrostFlower(e);return;}
 e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;a.linkTimer-=dt;if(a.linkTimer<=0){a.linkTimer=.2;a.links=a.targets.filter(other=>frostFlowerAlly(e,other));}
 while(a.pulses<2&&e.elapsed>=Math.round((.9+a.pulses*.8)*1e6)/1e6){a.pulses++;for(let other of a.targets)if(frostFlowerAlly(e,other)){let before=other.hp;other.hp=Math.min(other.max,other.hp+other.max*.08);if(other.hp>before)burst(other.x,other.y,28,'#a7efd9');}playSound('frost',e.x,e.y);}
 if(!a.fired&&e.elapsed>=2.1){a.fired=true;e.struck=true;if(dist(p,a.origin)<=180+1e-8&&lineClear(a.origin,p))hurt(44);burst(e.x,e.y,180,'#b8e7f2');playSound('frost',e.x,e.y);}
 if(e.elapsed>=2.8){e.attack=null;e.state='idle';e.t=3.5;}
};
const frostFlowerDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r5e6'||!frostFlowerSheet.complete||!frostFlowerSheet.naturalWidth||!frostFlowerSheet.naturalHeight)return frostFlowerDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0);if(e.hp<=0||e.frostWilt>0)f={row:2,col:3};else if(e.attack?.pattern==='frostFlowerMend')f={row:2,col:e.elapsed<.45?0:e.elapsed<2.1?1:2};let q=project(e.x,e.y),sw=frostFlowerSheet.naturalWidth/4,sh=frostFlowerSheet.naturalHeight/3,w=190,h=w*sh/sw,anchor=[.91,.88,.87][f.row];ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,frostFlowerSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(frostFlowerSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const frostFlowerSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r5e6'?125:frostFlowerSizeBase(e);
const frostFlowerGroundBase=drawGroundEffects;drawGroundEffects=()=>{frostFlowerGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r5e6'):enemies)){let a=e.attack;if(e.species!=='r5e6'||e.hp<=0||a?.pattern!=='frostFlowerMend'||!visibleAt(e.x,e.y))continue;if(!a.fired){groundRing(e.x,e.y,180,'#99d7ec',1);if(e.elapsed>=1.7)groundRing(e.x,e.y,180*Math.max(0,1-(e.elapsed-1.7)/.4),'#dff8ff',2);}if(a.pulses<2){let from=project(e.x,e.y);ctx.save();ctx.strokeStyle='#8de4c8';ctx.lineWidth=2;for(let other of a.links)if(other.hp>0){let to=project(other.x,other.y);ctx.beginPath();ctx.moveTo(from.x,from.y-45);ctx.lineTo(to.x,to.y-20);ctx.stroke();}ctx.restore();}}};
